"""Auditable scene→plan→cached synthesis→playback prototype; not production routing."""
import json,html,sys
from pathlib import Path

def main(folder):
 p=Path(folder);m=json.loads((p/'manifest.json').read_text());a=json.loads((p/'acoustic_analysis.json').read_text());r=json.loads((p/'report.json').read_text());asr={x['file']:x for x in json.loads((p/'asr_audit.json').read_text())}
 bank={}
 for row in m['instruction_items']:
  bank[row['id']]={'text':row['text'],'takes':{}}
  for seed in m['seeds']:
   for mode in m['instructions']:
    key=f'{row["id"]}_{mode}_s{seed}';item=next(i for i in r['items'] if i['file']==key+'.wav');met=next(i for i in a['instruction_pairs'] if i['id']==row['id'] and i['mode']==mode and i['seed']==seed)
    bank[row['id']]['takes'][f'{mode}_{seed}']={'src':'listening/'+key+'_group.mp3','instruction':m['instructions'][mode],'generation_seconds':item['elapsed_seconds'],'actual_instruction_tokens':item['instruction_at_model'],'asr':asr[item['file']],'metrics':met}
 data={'bank':bank,'summary':a['instruction_summary'],'limitations':['007번 여성 성우만 사용','규칙 기반 연출기: 자유로운 장면 이해 모델 아님','사전 생성한 동일 조건 음성을 재생하며 새 실시간 합성으로 가장하지 않음','지시 전달·음향 변화와 올바른 감정 표현은 별도 검증','어절별 속도·정확한 쉼 길이·웃음/숨 삽입은 현재 제어 미지원','운영 앱 연결·모델 교체 미적용']}
 options=''.join('<option value="'+row['id']+'">'+html.escape(row['text'])+'</option>' for row in m['instruction_items'])
 page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>미로 · 장면별 음성 연출 시연</title><style>body{margin:0;background:#f6f5ef;color:#252923;font:16px/1.65 system-ui}main{max-width:900px;margin:38px auto;padding:0 20px}h1{font-size:30px}h2{font-size:20px}section{background:white;border:1px solid #ddd;border-radius:16px;padding:24px;margin:18px 0}select,textarea,button{font:inherit;box-sizing:border-box}select,textarea{display:block;width:100%;padding:12px;border:1px solid #bbb;border-radius:8px;margin:10px 0}textarea{height:90px}button{padding:12px 18px;border:0;border-radius:8px;background:#35492d;color:white;cursor:pointer}.note{color:#606a5b;font-size:14px}pre{white-space:pre-wrap;word-break:break-word;background:#f3f4ee;padding:16px;font:13px/1.6 ui-monospace,monospace}audio{width:100%}.steps{display:flex;flex-wrap:wrap;gap:8px}.steps span{background:#e7eadf;border-radius:20px;padding:8px 12px}.warn{background:#fff1d7;padding:15px;border-radius:8px}label{font-weight:600}</style><main><small>MIRO · 007 기술 검증 · 추가 학습 없음</small><h1>장면이 달라지면 어떻게 말할까?</h1><p>장면 → 연출 계획 → Qwen 지시 전달 → 생성 결과 → 재생까지 확인하는 제한된 시연입니다.</p><p class="warn">같은 조건으로 미리 생성한 실험 음성을 재생합니다. 아래 장면 판단은 규칙 기반입니다. 감정을 정확히 이해하거나 운영 품질을 달성했다고 주장하지 않습니다.</p><div class="steps"><span>장면</span>→<span>연출 계획</span>→<span>모델 제어</span>→<span>음성</span>→<span>확인</span></div><section><label for="line">같은 대사 선택</label><select id="line">OPTIONS</select><label for="scene">장면 예시</label><select id="scene"><option value="none">평소처럼 차분히 대화한다.</option><option value="happy">반가운 재회에 기쁜 마음을 표현한다.</option><option value="sad">슬픔을 억누르며 상대에게 말한다.</option><option value="angry">질투와 분노를 억누르다 감정이 드러난다.</option><option value="whisper">귓가에 조용히 속삭이며 말한다.</option></select><label for="context">장면 설명 · 지원 키워드 범위에서 판정</label><textarea id="context">평소처럼 차분히 대화한다.</textarea><label for="seed">반복 확인</label><select id="seed"><option value="1234">시드 1234</option><option value="4321">시드 4321</option></select><button id="run">연출 계획 확인하고 샘플 재생</button></section><section><h2>연출 계획과 실제 지원 범위</h2><pre id="plan">장면을 선택한 뒤 실행해 주세요.</pre></section><section><h2 id="take-title">생성된 007 음성</h2><audio id="audio" controls></audio><p id="status" aria-live="polite"></p><p id="transcript"></p><details><summary>실제 모델 입력과 생성 기록</summary><pre id="evidence"></pre></details><p class="note">억양·상황 적합성·캐릭터 일관성은 직접 청취 확인이 필요합니다. 받아쓰기 점수는 감정 점수가 아닙니다.</p></section><p><a href="compare.html">원본·코덱·다섯 지시 전체 비교로 돌아가기</a></p></main><script id="data" type="application/json">DATA</script><script>const data=JSON.parse(document.querySelector('#data').textContent),$=x=>document.querySelector(x);const names={none:'보통 대화',happy:'기쁨',sad:'슬픔',angry:'분노',whisper:'속삭임'};function direct(context){if(/속삭|귓가|귀에|소곤/.test(context))return 'whisper';if(/분노|화가|화남|질투/.test(context))return 'angry';if(/슬픔|슬프|서운|눈물/.test(context))return 'sad';if(/기쁨|기쁜|반가|행복/.test(context))return 'happy';return 'none'}$('#scene').onchange=()=>{$('#context').value=$('#scene').selectedOptions[0].textContent};$('#run').onclick=()=>{const sid=$('#line').value,seed=$('#seed').value,context=$('#context').value,mode=direct(context),row=data.bank[sid],take=row.takes[mode+'_'+seed];const plan={voice:'007',text:row.text,scene:context,selected_delivery:names[mode],director:'규칙 기반 시연',instruction:take.instruction||'(지시 없음)',support:{style_instruction:'모델에 실제 전달됨; 의미적 준수는 청취 확인 필요',phrase_timing:'미지원',nonverbal_insertion:'미지원'},replay:'사전 생성 결과',seed:Number(seed)};$('#plan').textContent=JSON.stringify(plan,null,2);$('#take-title').textContent='007 · '+names[mode];$('#audio').src=take.src;$('#status').textContent='저장된 실험 음성 재생 · 실제 생성 소요 '+take.generation_seconds.toFixed(1)+'초 (첫 소리 지연 아님)';$('#transcript').textContent='자동 받아쓰기: '+take.asr.transcript;$('#evidence').textContent=JSON.stringify(take,null,2);$('#audio').play().catch(()=>$('#status').textContent+=' · ▶ 버튼을 눌러 주세요.')} </script></html>'''.replace('OPTIONS',options).replace('DATA',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
 (p/'pipeline.html').write_text(page);(p/'director_demo_data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print('Wrote scene director and 30 cached synthesis routes')
if __name__=='__main__':main(sys.argv[1])
